/** Validate a compact read_retrieval FlowRequest; output the same envelope, with no I/O or source payloads.
 * Inputs: flow/request_id and bounded scalar inputs. Output: one n8n item. Pick for the generic named-flow caller.
 * Byline: Codex · GPT-6.1-Sol · 2026-10-06.
 */
const item=$input.first()||{};
const body=item.json?.body ?? item.json;
if(item.binary || !body || typeof body!=='object' || Array.isArray(body)) throw new Error('Invalid retrieval envelope');
if(Object.keys(body).sort().join(',')!=='flow,inputs,request_id' || body.flow!=='read_retrieval') throw new Error('Unsupported retrieval envelope');
if(typeof body.request_id!=='string' || !/\S/.test(body.request_id) || body.request_id.length>2048) throw new Error('Invalid request identity');
const i=body.inputs;
const allowed=['query','leg_names','mode','scope_json','limit','per_leg_limit','leg_timeout_seconds'];
if(!i || typeof i!=='object' || Array.isArray(i) || Object.keys(i).some(k=>!allowed.includes(k))) throw new Error('Unsupported retrieval inputs');
if(typeof i.query!=='string' || !/\S/.test(i.query) || i.query.length>2000) throw new Error('Invalid retrieval query');
if(typeof i.leg_names!=='string') throw new Error('Invalid leg names');
const legs=i.leg_names.split(',');
if(legs.length<1 || legs.length>4 || new Set(legs).size!==legs.length || legs.some(n=>!/^[a-z][a-z0-9_]{0,63}$/.test(n))) throw new Error('Invalid leg names');
for(const [key,max] of [['limit',50],['per_leg_limit',100]]) if(i[key]!==undefined && (!Number.isInteger(i[key]) || i[key]<1 || i[key]>max)) throw new Error('Invalid retrieval limit');
if(i.leg_timeout_seconds!==undefined && (typeof i.leg_timeout_seconds!=='number' || !Number.isFinite(i.leg_timeout_seconds) || i.leg_timeout_seconds<=0 || i.leg_timeout_seconds>30)) throw new Error('Invalid retrieval deadline');
if(i.mode!==undefined && !['keyword','hybrid','vector'].includes(i.mode)) throw new Error('Invalid retrieval mode');
if(i.scope_json!==undefined) {
  if(typeof i.scope_json!=='string' || i.scope_json.length>16384) throw new Error('Invalid scope');
  let scope; try {scope=JSON.parse(i.scope_json);} catch {throw new Error('Invalid scope');}
  if(!scope || typeof scope!=='object' || Array.isArray(scope) || Object.keys(scope).some(k=>!['source_id','source_version_ids','thread_id','path_prefix'].includes(k))) throw new Error('Unsupported scope');
  for(const [key,value] of Object.entries(scope)) {
    /** Check one supplied scope coordinate; return validity without I/O or normalization. */
    const validId=v=>typeof v==='string' && /\S/.test(v) && v.length<=2048;
    if(key==='source_version_ids' ? (!Array.isArray(value) || value.length>32 || value.some(v=>!validId(v))) : (value!==null && !validId(value))) throw new Error('Invalid scope coordinate');
  }
}
return [{json:body}];

/** Validate the compact composition response without altering citations or hiding partial failures.
 * Input: retrieve_flow result. Output: the unchanged FlowResult. Effects: none; use before Respond to Webhook.
 * Byline: Codex · GPT-6.1-Sol · 2026-10-06.
 */
const body=$input.first()?.json;
if(!body || typeof body!=='object' || Array.isArray(body) || Object.keys(body).some(k=>!['flow','status','outputs'].includes(k))) throw new Error('Invalid retrieval result');
if(body.flow!=='read_retrieval' || !['success','failed'].includes(body.status)) throw new Error('Invalid flow result identity/status');
const out=body.outputs;
if(!out || !['success','partial','failed'].includes(out.status) || out.verification!=='coordinates_preserved' || !Array.isArray(out.items) || !Array.isArray(out.legs) || out.legs.length<1 || out.legs.length>4 || out.items.length>50) throw new Error('Invalid retrieval outputs');
if((out.status==='failed')!==(body.status==='failed') || out.items.some(h=>!h.citation?.collection || !h.citation?.object_id || Object.hasOwn(h,'text'))) throw new Error('Invalid compact citation result');
if(out.request_id!==$('Validate flow request').first().json.request_id) throw new Error('Mismatched retrieval request identity');
if(Object.keys(out).some(k=>!['request_id','mode','scope','status','items','legs','verification'].includes(k))) throw new Error('Unsupported output field');
if(!['keyword','hybrid','vector'].includes(out.mode) || !out.scope || typeof out.scope!=='object' || Array.isArray(out.scope)) throw new Error('Invalid returned context');
if(out.legs.some(l=>!['success','failed'].includes(l.status))) throw new Error('Invalid leg status');
const failures=out.legs.filter(l=>l.status==='failed').length;
const expected=failures===out.legs.length?'failed':failures?'partial':'success';
if(out.status!==expected || (expected==='failed' && out.items.length)) throw new Error('Hidden leg failure');
if(Buffer.byteLength(JSON.stringify(body),'utf8')>65536) throw new Error('Compact response exceeds Activity bound');
return [{json:body}];
